CREATE TABLE matzang_fields(field_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,active BOOLEAN NOT NULL DEFAULT FALSE,resting BOOLEAN NOT NULL DEFAULT FALSE,rest_until DATETIME(3) NULL,max_count INT UNSIGNED NOT NULL DEFAULT 10,win_pt_min INT UNSIGNED NOT NULL DEFAULT 10,win_pt_max INT UNSIGNED NOT NULL DEFAULT 15,lose_pt_min INT UNSIGNED NOT NULL DEFAULT 5,lose_pt_max INT UNSIGNED NOT NULL DEFAULT 7,win_reward_point DECIMAL(30,3) NOT NULL DEFAULT 50000000,lose_reward_point DECIMAL(30,3) NOT NULL DEFAULT 25000000,version BIGINT UNSIGNED NOT NULL DEFAULT 1,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(field_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE matzang_participants(field_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,player_id BIGINT UNSIGNED NOT NULL,display_name VARCHAR(191) NOT NULL,active BOOLEAN NOT NULL DEFAULT FALSE,eliminated BOOLEAN NOT NULL DEFAULT FALSE,match_count INT UNSIGNED NOT NULL DEFAULT 0,pt BIGINT UNSIGNED NOT NULL DEFAULT 0,wins BIGINT UNSIGNED NOT NULL DEFAULT 0,losses BIGINT UNSIGNED NOT NULL DEFAULT 0,total_exp BIGINT UNSIGNED NOT NULL DEFAULT 0,pet_type VARCHAR(32) NULL,upgrade_level INT UNSIGNED NOT NULL DEFAULT 0,total_exp_updated_at DATETIME(3) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,PRIMARY KEY(field_key,player_id),KEY idx_matzang_rank(field_key,pt,display_name),CONSTRAINT fk_matzang_participant_field FOREIGN KEY(field_key) REFERENCES matzang_fields(field_key) ON DELETE CASCADE,CONSTRAINT fk_matzang_participant_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE matzang_battles(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,operation_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,attacker_player_id BIGINT UNSIGNED NOT NULL,defender_player_id BIGINT UNSIGNED NOT NULL,winner_player_id BIGINT UNSIGNED NOT NULL,loser_player_id BIGINT UNSIGNED NOT NULL,attacker_base BIGINT UNSIGNED NOT NULL,attacker_buffed BIGINT UNSIGNED NOT NULL,attacker_final BIGINT UNSIGNED NOT NULL,defender_base BIGINT UNSIGNED NOT NULL,defender_buffed BIGINT UNSIGNED NOT NULL,defender_final BIGINT UNSIGNED NOT NULL,gained_pt INT UNSIGNED NOT NULL,reward_point DECIMAL(30,3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uq_matzang_battle_operation(operation_id),CONSTRAINT fk_matzang_battle_operation FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE RESTRICT,CONSTRAINT fk_matzang_battle_field FOREIGN KEY(field_key) REFERENCES matzang_fields(field_key) ON DELETE RESTRICT,CONSTRAINT fk_matzang_battle_attacker FOREIGN KEY(attacker_player_id) REFERENCES players(id) ON DELETE RESTRICT,CONSTRAINT fk_matzang_battle_defender FOREIGN KEY(defender_player_id) REFERENCES players(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE matzang_rng_samples(operation_id BIGINT UNSIGNED NOT NULL,sequence_no INT UNSIGNED NOT NULL,sample_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,sample_value DECIMAL(20,19) NOT NULL,outcome_code VARCHAR(191) NOT NULL,PRIMARY KEY(operation_id,sequence_no),CONSTRAINT fk_matzang_rng_operation FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO matzang_fields(field_key) VALUES('current') ON DUPLICATE KEY UPDATE field_key=VALUES(field_key);
